const fs = require('fs');
const cq = $input.first().json.callback_query;
const data = cq?.data || '';
const callbackId = cq?.id;
const chatId = cq?.message?.chat?.id;

// Parse: email_ok::MSG_ID or email_noise::MSG_ID
const [action, msgId] = data.split('::');
if (!action || !msgId || !action.startsWith('email_')) {
  return [{ json: { callbackId, chatId, handled: false, note: 'not email callback' } }];
}

const label = action === 'email_ok' ? 'important' : 'noise';

// Load signals file
const sigPath = '/memory/email_signals.json';
let store = { signals: [], pending: {} };
try { store = JSON.parse(fs.readFileSync(sigPath, 'utf8')); } catch(e) {}

// Get context from pending
const pending = store.pending?.[msgId] || {};
const fromEmail = pending.from_email || 'unknown';
const fromName = pending.from_name || '';
const subject = pending.subject || '';

// Update or add signal
const existing = store.signals.find(s => s.from_email === fromEmail);
if (existing) {
  existing.label = label;
  existing.count = (existing.count || 1) + 1;
  existing.last_subject = subject;
} else {
  store.signals.push({ from_email: fromEmail, from_name: fromName, last_subject: subject, label, count: 1 });
}

// Remove from pending
delete store.pending[msgId];
fs.writeFileSync(sigPath, JSON.stringify(store, null, 2));

return [{ json: { callbackId, chatId, label, fromEmail, handled: true } }];

const fs = require('fs');
let projects = [];
let current = null;
try { const s = JSON.parse(fs.readFileSync('/memory/projects.json', 'utf8')); projects = s.projects || []; } catch(e) {}
try { const s = JSON.parse(fs.readFileSync('/memory/current_project.json', 'utf8')); current = s.currentProject || null; } catch(e) {}
const list = projects.length > 0
  ? projects.map((p, i) => (i+1) + '. ' + p + (p === current ? ' ✅' : '')).join('\n')
  : 'No projects found.';
const reply = '📁 <b>Projects:</b>\n\n' + list + '\n\n<i>Use /setproject &lt;name&gt; to select one</i>';
return [{ json: { reply, chat_id: $input.first().json.chat_id } }];

const fs = require('fs');
let current = null;
try {
  const store = JSON.parse(fs.readFileSync('/memory/current_project.json', 'utf8'));
  current = store.currentProject || null;
} catch(e) {}
const reply = current
  ? '📌 <b>Current project:</b> ' + current + '\n<code>/mnt/data/projects/' + current + '</code>\n\nSend me any task and I will run it via Claude Code.'
  : '❌ No project set.\n\nUse /setproject &lt;name&gt; to select one, or /listprojects to see available projects.';
return [{ json: { reply, chat_id: $input.first().json.chat_id } }];

const fs = require('fs');
const text = $input.first().json.message_text || '';
const chat_id = $input.first().json.chat_id;
const parts = text.trim().split(/\s+/);
const arg = parts.slice(1).join(' ').trim().toLowerCase();
if (!arg) {
  return [{ json: { noArg: true, matched: null, arg: '', projects: [], chat_id,
    reply: 'Usage: /setproject &lt;project-name&gt;\n\nUse /listprojects to see available projects.' } }];
}
let projects = [];
try {
  const store = JSON.parse(fs.readFileSync('/memory/projects.json', 'utf8'));
  projects = store.projects || [];
} catch(e) {}
const exact = projects.find(p => p.toLowerCase() === arg);
return [{ json: { noArg: false, matched: exact || null, arg, projects, chat_id } }];

const fs = require('fs');
const item = $input.first().json;
if (item.noArg) {
  return [{ json: { reply: item.reply, chat_id: item.chat_id } }];
}
fs.writeFileSync('/memory/current_project.json', JSON.stringify({ currentProject: item.matched }));
const reply = '✅ Project set to <b>' + item.matched + '</b>\n<code>/mnt/data/projects/' + item.matched + '</code>\n\nSend me any task and Claude Code will work on it.';
return [{ json: { reply, chat_id: item.chat_id } }];

const fs = require('fs');
const content = ($input.first().json.message?.content || '').trim();
const origItem = $('Extract Setproject Arg').first().json;
const projects = origItem.projects || [];
const chat_id = origItem.chat_id;
const matched = projects.find(p => p.toLowerCase() === content.toLowerCase()) || content;
fs.writeFileSync('/memory/current_project.json', JSON.stringify({ currentProject: matched }));
const reply = '✅ Project set to <b>' + matched + '</b> <i>(closest match to "' + origItem.arg + '")</i>\n<code>/mnt/data/projects/' + matched + '</code>\n\nSend me any task and Claude Code will work on it.';
return [{ json: { reply, chat_id } }];

const cmd = ($input.first().json.message_text || '').split(' ')[0];
const reply = '❓ Unknown command: <code>' + cmd + '</code>

Available commands:
/setproject &lt;name&gt; — set active project
/project — show current project
/listprojects — list all projects';
return [{ json: { reply, chat_id: $input.first().json.chat_id } }];

const fs = require('fs');
let project = null;
try {
  const store = JSON.parse(fs.readFileSync('/memory/current_project.json', 'utf8'));
  project = store.currentProject || null;
} catch(e) {}

const cwd     = project ? '/mnt/data/projects/' + project : '/mnt/data/Bill';
const docsBase = project
  ? '/mnt/data/projects/' + project + '/docs'
  : '/mnt/data/Bill/docs';

const msg     = $('Extract Message').item.json.message_text;
const chat_id = $('Extract Message').item.json.chat_id;

let system = '';
try {
  system = fs.readFileSync('/memory/relay-system-prompt.txt', 'utf8').trim();
} catch(e) {}

// Inject last exchange as immediate short-term context
let recentContext = '';
try {
  const last = JSON.parse(fs.readFileSync('/memory/last_exchange.json', 'utf8'));
  if (last.user && last.bot) {
    recentContext = 'RECENT CONVERSATION (immediately before this message):\nUser: ' + last.user + '\nAssistant: ' + last.bot + '\n\n';
  }
} catch(e) {}

// Inject relevant Qdrant memory context
let memoryContext = '';
try {
  const results = ($input.first().json.result || []).slice(0, 4);
  const snippets = results.map(r => {
    try { return JSON.parse(r.payload?.content || '{}').text || ''; } catch { return ''; }
  }).filter(s => s.length > 20);
  if (snippets.length > 0) {
    memoryContext = 'RELEVANT PAST CONTEXT (for reference only):\n' + snippets.join('\n---\n') + '\n\n';
  }
} catch(e) {}

return [{ json: { cwd, docsBase, prompt: recentContext + memoryContext + msg, system, message_text: msg, chat_id, project } }];

const item = $input.first().json;
const chat_id = $('Extract Message').item.json.chat_id;
if (item.error) {
  return [{ json: { reply: '⚠️ Claude Code failed:\n<code>' + (item.error.message || item.error) + '</code>', chat_id, hasFile: false } }];
}
if (!item.ok && item.output) {
  return [{ json: { reply: '⚠️ Claude returned an error:\n<code>' + item.output + '</code>', chat_id, hasFile: false } }];
}
const out = (item.output || '').trim();
if (!out) {
  return [{ json: { reply: '⚠️ Claude Code returned no output.', chat_id, hasFile: false } }];
}

// Detect [FILE:/absolute/path] marker — last match wins
const fileMatch = [...out.matchAll(/\[FILE:([^\]]+)\]/g)].pop();
if (fileMatch) {
  const hostPath = fileMatch[1].trim();
  // Translate host paths to container paths
  let containerPath = hostPath
    .replace('/mnt/data/projects/', '/projects/')
    .replace('/mnt/data/Bill/', '/bill/');
  const description = out.replace(/\[FILE:[^\]]+\]/g, '').trim();
  return [{ json: { reply: description || 'Document ready.', chat_id, hasFile: true, filePath: containerPath, hostPath } }];
}

return [{ json: { reply: out, chat_id, hasFile: false } }];

const fs = require('fs');
const item = $input.first().json;
let currentProject = null;
try {
  const store = JSON.parse(fs.readFileSync('/memory/current_project.json', 'utf8'));
  currentProject = store.currentProject || null;
} catch(e) {}
return [{ json: { ...item, currentProject } }];

const http = require('http');

const chat_id = $json.chat_id;
const payload  = JSON.stringify({
  prompt: $json.prompt,
  cwd:    $json.cwd,
  system: $json.system || ''
});

return new Promise((resolve, reject) => {
  const req = http.request({
    hostname: 'mcp-shell',
    port:     3007,
    path:     '/claude',
    method:   'POST',
    headers: {
      'Content-Type':   'application/json',
      'Content-Length': Buffer.byteLength(payload)
    },
    timeout: 300000
  }, (res) => {
    let data = '';
    res.on('data', c => { data += c; });
    res.on('end', () => {
      try {
        const json = JSON.parse(data);
        resolve([{ json: { ...json, chat_id } }]);
      } catch(e) {
        reject(new Error('Bad JSON from claude-http-server: ' + data.slice(0, 200)));
      }
    });
  });
  req.on('timeout', () => {
    req.destroy();
    reject(new Error('Claude HTTP request timed out after 300s'));
  });
  req.on('error', reject);
  req.write(payload);
  req.end();
});

const fs = require('fs');
const https = require('https');
const path = require('path');

const chat_id = $('Handle Relay Result').item.json.chat_id;
const filePath = $('Handle Relay Result').item.json.filePath;
const caption = ($('Handle Relay Result').item.json.reply || '').substring(0, 1024);
const token = $env.TELEGRAM_BOT_TOKEN;

if (!fs.existsSync(filePath)) {
  throw new Error('File not found: ' + filePath);
}

const fileContent = fs.readFileSync(filePath);
const filename = path.basename(filePath);
const boundary = '----TGBoundary' + Date.now();
const CRLF = '\r\n';

const part = (name, val) =>
  `--${boundary}${CRLF}Content-Disposition: form-data; name="${name}"${CRLF}${CRLF}${val}${CRLF}`;

const prologue = Buffer.from([
  part('chat_id', String(chat_id)),
  part('caption', caption),
  `--${boundary}${CRLF}Content-Disposition: form-data; name="document"; filename="${filename}"${CRLF}Content-Type: text/html; charset=utf-8${CRLF}${CRLF}`
].join(''));
const epilogue = Buffer.from(`${CRLF}--${boundary}--${CRLF}`);
const body = Buffer.concat([prologue, fileContent, epilogue]);

return new Promise((resolve, reject) => {
  const req = https.request({
    hostname: 'api.telegram.org',
    path: `/bot${token}/sendDocument`,
    method: 'POST',
    headers: {
      'Content-Type': `multipart/form-data; boundary=${boundary}`,
      'Content-Length': body.length
    },
    timeout: 30000
  }, (res) => {
    let data = '';
    res.on('data', c => data += c);
    res.on('end', () => {
      try {
        const json = JSON.parse(data);
        if (!json.ok) return reject(new Error('Telegram error: ' + data));
        resolve([{ json: { sent: true, file: filePath, chat_id, reply: caption } }]);
      } catch(e) { reject(e); }
    });
  });
  req.on('error', reject);
  req.write(body);
  req.end();
});

const fs = require('fs');
const item = $input.first().json;
const userMsg = $('Extract Message').item.json.message_text || '';
const botReply = item.reply || '';
const project  = $('Build Relay Input').item.json.project || null;

try {
  fs.writeFileSync('/memory/last_exchange.json', JSON.stringify({
    user: userMsg,
    bot: botReply,
    project,
    timestamp: new Date().toISOString()
  }));
} catch(e) {}

return [$input.first()];

const points = $input.item.json.result?.points ?? [];
const texts = points.map(p => p.payload?.text ?? '').filter(Boolean);
return { json: { conversation_dump: texts.join('\n---\n'), point_ids: points.map(p => p.id) } };

