const fs = require('fs');
const sigPath = '/memory/email_signals.json';
let store = { signals: [], pending: {} };
try { store = JSON.parse(fs.readFileSync(sigPath, 'utf8')); } catch(e) {}

const sd = $getWorkflowStaticData('global');
const lastCheck = sd.lastCheck || new Date(Date.now() - 15*60*1000).toISOString();
sd.lastCheck = new Date().toISOString();

return [{ json: { lastCheck, signals: store.signals, pending: store.pending || {} } }];

const raw = $input.first().json.output || '';
let emails = [];
try {
  const match = raw.match(/\[[\s\S]*\]/);
  if (match) emails = JSON.parse(match[0]);
} catch(e) {}

const sd = $getWorkflowStaticData('global');
const seenIds = new Set(sd.seenIds || []);
const newEmails = emails.filter(e => e.id && !seenIds.has(e.id));

// Mark all as seen immediately
newEmails.forEach(e => seenIds.add(e.id));
const arr = Array.from(seenIds);
sd.seenIds = arr.slice(-600); // keep last 600

if (newEmails.length === 0) return [];
return newEmails.map(e => ({ json: e }));

const e = $input.first().json;
const sys = 'Is this email spam, a newsletter, marketing, or an automated notification? Return JSON only: {"skip": true, "reason": "spam|newsletter|marketing|automated"}. For genuine personal email, business correspondence, invoice, or anything requiring human attention return {"skip": false, "reason": "genuine"}.';
return [{ json: {
  model: 'qwen2.5:14b',
  messages: [
    { role: 'system', content: sys },
    { role: 'user', content: 'From: ' + e.from_name + ' <' + e.from_email + '>\nSubject: ' + e.subject + '\nPreview: ' + (e.snippet || '') }
  ],
  stream: false,
  options: { temperature: 0.1 }
}}];

const emailData = $('Parse & Split').item.json;
const content = $input.first().json.message?.content || '';
let triage = { skip: false, reason: 'parse_error' };
try {
  const match = content.match(/\{[^}]+\}/);
  if (match) triage = JSON.parse(match[0]);
} catch(e) {}
return [{ json: { ...emailData, skip: triage.skip, triage_reason: triage.reason } }];

const fs = require('fs');
let signals = [];
try {
  const store = JSON.parse(fs.readFileSync('/memory/email_signals.json', 'utf8'));
  signals = store.signals || [];
} catch(e) {}

const e = $input.first().json;
const sigCtx = signals.length > 0
  ? signals.slice(-15).map(s => '- ' + s.from_email + ' → ' + s.label + ' (' + (s.last_subject||'') + ')').join('\n')
  : 'No signals yet.';

const prompt = `Score this email's interrupt-worthiness 1-10 for a busy professional.

Past user feedback:
${sigCtx}

Email:
From: ${e.from_name} <${e.from_email}>
Subject: ${e.subject}
Preview: ${e.snippet || ''}

Rules: 9-10 = urgent/time-sensitive. 7-8 = worth reading soon. 1-6 = can wait or ignore.
Return JSON only: {"score": N, "reason": "one sentence"}`;

return [{ json: {
  ...e,
  llm_body: {
    model: 'qwen2.5:14b',
    messages: [{ role: 'user', content: prompt }],
    stream: false,
    options: { temperature: 0.2 }
  }
}}];

const fs = require('fs');
const emailData = $('Build Score Prompt').item.json;
const content = $input.first().json.message?.content || '';

let scoring = { score: 5, reason: 'could not parse' };
try {
  const match = content.match(/\{[^}]+\}/);
  if (match) scoring = JSON.parse(match[0]);
} catch(e) {}

const score = Number(scoring.score) || 5;

// Save to pending so callback handler has context
if (score >= 7) {
  const sigPath = '/memory/email_signals.json';
  let store = { signals: [], pending: {} };
  try { store = JSON.parse(fs.readFileSync(sigPath, 'utf8')); } catch(e) {}
  store.pending = store.pending || {};
  store.pending[emailData.id] = {
    from_email: emailData.from_email,
    from_name: emailData.from_name,
    subject: emailData.subject,
    score
  };
  // Prune pending older than 50 entries
  const keys = Object.keys(store.pending);
  if (keys.length > 50) delete store.pending[keys[0]];
  fs.writeFileSync(sigPath, JSON.stringify(store, null, 2));
}

return [{ json: { ...emailData, score, score_reason: scoring.reason } }];

