const fs = require('fs');
const base = '/projects';
let projects = [];
try {
  projects = fs.readdirSync(base)
    .filter(f => !f.startsWith('.') && fs.statSync(base + '/' + f).isDirectory());
} catch(e) {
  return [{ json: { error: e.message, projects: [] } }];
}
return [{ json: { projects, count: projects.length } }];

const fs = require('fs');
